## Primary Task: Add Workspace Keyboard Shortcut Test

Add a new test to the END of `tests/browser/browser_mogwser_workspaces.js` (after the existing 4 tests). This test should verify that Ctrl+1..9 keyboard shortcuts switch workspaces:

```js
add_task(async function test_keyboard_shortcut_switches_workspace() {
  const workspaces = window.gMogwserWorkspaces;

  // Create two workspaces so we have something to switch between
  const ws1 = workspaces.createWorkspace("Shortcut WS 1", "1\uFE0F\u20E3");
  const ws2 = workspaces.createWorkspace("Shortcut WS 2", "2\uFE0F\u20E3");

  // Get workspace IDs in order
  const allIds = workspaces.getAllWorkspaceIds();

  // Switch to first workspace position using Ctrl+1
  workspaces.switchWorkspace(allIds[0]);
  Assert.equal(
    workspaces.activeWorkspaceId,
    allIds[0],
    "Should be on first workspace"
  );

  // Simulate Ctrl+2 to switch to second workspace position
  const event = new KeyboardEvent("keydown", {
    key: "2",
    code: "Digit2",
    ctrlKey: true,
    bubbles: true,
  });
  window.dispatchEvent(event);

  Assert.equal(
    workspaces.activeWorkspaceId,
    allIds[1],
    "Ctrl+2 should switch to second workspace"
  );

  // Cleanup
  workspaces.deleteWorkspace(ws1.id);
  workspaces.deleteWorkspace(ws2.id);
});
```

IMPORTANT: Read the actual MogwserWorkspaces.mjs to verify:
- The method name for getting all workspace IDs (might be `getAllWorkspaceIds()` or iterate `_workspaces.keys()`)
- How `_onKeyDown` maps Ctrl+digit to workspace index
- The test must match the actual API

