## Task 1: Add rgbToHsl Roundtrip Tests (test_theme_colors.js)

Read `src/mogwser/themes/MogwserGradientPicker.mjs` first to verify the exact method names for `rgbToHsl` and `hslToRgb`. Then add these tests at the END of `tests/unit/test_theme_colors.js`:

```js
add_task(async function test_rgb_to_hsl_roundtrip_red() {
  const rgb = MogwserGradientPicker.hslToRgb(0, 100, 50);
  const hsl = MogwserGradientPicker.rgbToHsl(rgb.r, rgb.g, rgb.b);
  Assert.equal(hsl.h, 0, "Roundtrip red hue should be 0");
  Assert.equal(hsl.s, 100, "Roundtrip red saturation should be 100");
  Assert.equal(hsl.l, 50, "Roundtrip red lightness should be 50");
});

add_task(async function test_rgb_to_hsl_roundtrip_cyan() {
  const rgb = MogwserGradientPicker.hslToRgb(180, 50, 60);
  const hsl = MogwserGradientPicker.rgbToHsl(rgb.r, rgb.g, rgb.b);
  Assert.equal(hsl.h, 180, "Roundtrip cyan hue should be 180");
  // Allow +/-1 for rounding
  Assert.ok(Math.abs(hsl.s - 50) <= 1, "Roundtrip cyan saturation should be ~50");
  Assert.ok(Math.abs(hsl.l - 60) <= 1, "Roundtrip cyan lightness should be ~60");
});
```

